    this._hass = h;
    if (!this._config || !h) return;
    const ids = this.watched(), st = h.states || {}, prev = this._sig;
    let same = Array.isArray(prev) && prev.length === ids.length * 2;
    for (let i = 0; same && i < ids.length; i++) same = prev[2 * i] === ids[i] && prev[2 * i + 1] === st[ids[i]];
    if (same) return;
