    const cs = c.clock && (c.clock_size === "big" || c.clock_size === "huge") ? " cs-" + c.clock_size : "";
    const {root, face} = this.paper(c.entity, {cls: "press", face: "w" + cs});
    root.tabIndex = 0; root.setAttribute("role", "button");
